#include <stdio.h>

static void swap(int *pa, int *pb) {
    int t = *pa;
    *pa = *pb;
    *pb = t;
}

int main(void) {
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 0;
    swap(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int data[100];
    int *p = data;
    for (int i = 0; i < n; i++) {
        if (scanf("%d", p + i) != 1) return 0;
    }
    int *lo = p;
    int *hi = p + (n - 1);
    while (lo < hi) {
        int t = *lo;
        *lo = *hi;
        *hi = t;
        lo++;
        hi--;
    }
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        printf("%d", *(p + i));
    }
    putchar('\n');
    return 0;
}

